import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.F7eQ-ohH.js";const m=JSON.parse('{"title":"关于央国企校招的加分项","description":"","frontmatter":{},"headers":[],"relativePath":"docs/简历优化/4.国央企简历加分项.md","filePath":"docs/简历优化/4.国央企简历加分项.md","lastUpdated":1788881428000}'),s={name:"docs/简历优化/4.国央企简历加分项.md"};function _(n,t,p,d,c,i){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="关于央国企校招的加分项" tabindex="-1">关于央国企校招的加分项 <a class="header-anchor" href="#关于央国企校招的加分项" aria-label="Permalink to &quot;关于央国企校招的加分项&quot;">​</a></h1><p><strong>1、硕士以上学历：</strong> 目前大型央企集团，二级以上公司的招聘要求对于学历这块儿已经上涨到硕士研究生以上了（未明确卡985/211），所以对于学历是本科的同学，想办法考研、保研才是去央国企最基本的要求。</p><p><strong>2、党员优先、校级以上获奖优先、国家级奖学金优先：</strong> 很多央国企招聘当中，会明确写明，相同情况下党员优先，大家还不是党员的同学抓紧机会入党，说不定有机会因为这个脱颖而出。星主本身是党员，在央企内部每月都会有党组织活动，党员的教育与普通员工还有所不同。</p><p>校级以上获奖和国家奖学金这个没啥好说的，同党员一样，有什么三好学生、优秀毕业生可以优先考虑。</p><p><strong>3、专业资格证书：</strong> 对于某些专业来说，提前考取国家认可的专业资格证书也是有助于你在面试过程中脱颖而出的。</p><p><strong>4、神秘力量：</strong> 这个需要让大家知道的是，依靠神秘力量去央国企的确实挺多的，但是并不是没有就进不去。至少我身边的同事90%都是走正规途径，靠校招、社招进去的，所以有这种情况，但是大家别过分妖魔化。</p><p>最后，其实还是那句话，核心的是学历/学校、党员、优秀学生、国家奖学金是锦上添花，有当然好，没有也不必去苛求，重点是消灭央国企就业过程中的信息差。</p>',7)])])}const f=a(s,[["render",_]]);export{m as __pageData,f as default};
